query.postgres:
WITH RECURSIVE search_tree AS ( SELECT r.id, r.headoffice_company_sungero FROM public.sungero_core_recipient r WHERE r.discriminator = '{0}' and r.headoffice_company_sungero = ANY(STRING_TO_ARRAY('{1}', ';')::bigint[])
UNION ALL
SELECT r.id, r.headoffice_company_sungero FROM public.sungero_core_recipient r JOIN search_tree st ON st.id = r.headoffice_company_sungero WHERE r.discriminator = '{0}' ) select STRING_AGG(cast(search_tree.id as text), ';') from search_tree;
